19	cat > src/checkout.ts << 'TS'
20	export function total(items: { price: number; qty: number }[]): number {
21	  return items.reduce((sum, item) => sum + item.price * item.qty, 0);
22	}
23	export function discountTotal(items: { price: number; qty: number }[], discount: number): number {
24	  const raw = total(items);
25	  return raw - discount;
26	}
