49	function runStepPilot(
50	  cmd: string,
51	  args: string[],
52	  cwd: string,
53	  timeoutMs: number,
54	): Promise<{ stdout: string; stderr: string; exitCode: number | null }> {
55	  return new Promise((resolve) => {
56	    let stdout = '';
57	    let stderr = '';
58	    let settled = false;
59	
60	    const finish = (err?: any) => {
61	      if (settled) return;
62	      settled = true;
63	      clearTimeout(timer);
64	      resolve({
65	        stdout,
66	        stderr,
67	        exitCode: err?.status ?? null,
68	      });
69	    };
70	
71	    const timer = setTimeout(() => finish(new Error('timeout')), timeoutMs);
72	
73	    // Windows cannot execute `.js` files directly via spawn without shell;
74	    // route them through `node` explicitly so we can capture stream-json output.
75	    const useShell = !cmd.endsWith('.js');
76	    const proc = useShell
77	      ? spawn(cmd, args, { cwd, stdio: ['pipe', 'pipe', 'pipe'], shell: true })
78	      : spawn('node', [cmd, ...args], { cwd, stdio: ['pipe', 'pipe', 'pipe'], shell: false });
79	
80	    proc.stdout.on('data', (data) => {
81	      stdout += data.toString();
82	    });
83	    proc.stderr.on('data', (data) => {
84	      stderr += data.toString();
85	    });
86	    proc.on('error', finish);
87	    proc.on('close', finish);
88	  });
89	}
