113	  const { stdout, stderr, exitCode } = await runStepPilot(cmd, args, join(__dirname, '..'), (task.timeout ?? 120) * 1000);
114	  const durationMs = Date.now() - startTime;
115	
116	  const events: RawEvent[] = [];
117	  let toolCalls = 0;
118	  let toolErrors = 0;
119	  let retries = 0;
120	  let compactions = 0;
121	  let inputTokens = 0;
122	  let outputTokens = 0;
123	  let totalTokens = 0;
124	  let stopReason: string | null = null;
125	  let failureReason: string | null = null;
126	  let turns = 0;
127	  let resultSubtype: string | null = null;
128	
129	  for (const line of stdout.split('\n')) {
130	    if (!line.trim()) continue;
131	    try {
132	      const ev = JSON.parse(line) as RawEvent;
133	      events.push(ev);
134	      captureMetrics(ev, {
135	        toolCalls: (updater) => (toolCalls = updater(toolCalls)),
136	        toolErrors: (updater) => (toolErrors = updater(toolErrors)),
137	        retries: (updater) => (retries = updater(retries)),
138	        compactions: (updater) => (compactions = updater(compactions)),
139	        inputTokens: (updater) => (inputTokens = updater(inputTokens)),
140	        outputTokens: (updater) => (outputTokens = updater(outputTokens)),
141	        totalTokens: (updater) => (totalTokens = updater(totalTokens)),
142	        stopReason: (v) => (stopReason = v),
