163	    category: task.category,
164	    profile,
165	    model: 'step-3.7-flash',
166	    provider: 'stepfun',
167	    step_pilot_commit: getGitCommit(),
168	    run_index: runIndex,
169	    success: success && checksFailed === 0,
170	    duration_ms: durationMs,
171	    turns,
