261	  if (!setupContent) return;
262	
263	  try {
264	    if (process.platform === 'win32') {
265	      const { mkdtempSync, mkdirSync, writeFileSync } = await import('node:fs');
266	      const { execSync } = await import('node:child_process');
267	      mkdirSync(repoDir, { recursive: true });
268	      const tmpDir = mkdtempSync(join(dirname(repoDir), 'bench-setup-'));
269	      const scriptPath = join(tmpDir, 'setup.sh');
270	      // Setup scripts compute TASK_DIR from $0; when copied to a temp file that
271	      // points to the temp path. Inject the real task directory instead.
272	      const taskDir = dirname(repoDir);
273	      // Git Bash on Windows requires MSYS-style paths for commands like mkdir.
274	      const msysTaskDir = '/d' + taskDir.slice(2).replace(/:/g, '');
275	      const fixedSetup = setupContent
276	        .replace(/^TASK_DIR=.*$/m, `TASK_DIR="${msysTaskDir}"`)
277	        .replace(/^REPO=.*$/m, `REPO="${msysTaskDir}/repo"`);
278	      writeFileSync(scriptPath, fixedSetup, 'utf8');
279	      try {
280	        const result = spawnSync('D:/Git/usr/bin/bash.exe', [scriptPath], {
281	          cwd: repoDir,
282	          encoding: 'utf8',
283	          stdio: 'pipe',
284	        });
285	        if (result.status !== 0) {
286	          const stderr = result.stderr?.toString() ?? '';
287	          const stdout = result.stdout?.toString() ?? '';
288	          throw new Error(`exit=${result.status} stderr=${stderr.slice(0, 500)} stdout=${stdout.slice(0, 200)}`);
289	        }
290	      } finally {
291	        try {
292	          // Make test files read-only so the agent cannot mutate them to fake success.
